cd /testbed && git apply <<'PATCH'
diff --git a/tokio/tests/sync_broadcast.rs b/tokio/tests/sync_broadcast.rs
--- a/tokio/tests/sync_broadcast.rs
+++ b/tokio/tests/sync_broadcast.rs
@@ -542,3 +542,45 @@ fn resubscribe_lagged() {
     assert_empty!(rx);
     assert_empty!(rx_resub);
 }
+
+#[test]
+fn resubscribe_closed() {
+    for capacity in [1, 4] {
+        let (tx, rx) = broadcast::channel::<u32>(capacity);
+        drop(tx);
+
+        let mut rx_resub = rx.resubscribe();
+        let mut rx_resub_recv = rx_resub.resubscribe();
+        drop(rx);
+
+        assert_closed!(rx_resub.try_recv());
+        let err = assert_ready_err!(task::spawn(rx_resub_recv.recv()).poll());
+        assert!(is_closed(err));
+    }
+}
+
+#[test]
+fn resubscribe_closed_with_unread_messages() {
+    for capacity in [1, 2, 4] {
+        let (tx, mut rx) = broadcast::channel(capacity);
+        for value in 0..capacity {
+            assert_ok!(tx.send(value));
+        }
+        drop(tx);
+
+        let mut rx_resub = rx.resubscribe();
+        let mut rx_resub_recv = rx.resubscribe();
+
+        assert_closed!(rx_resub.try_recv());
+        let err = assert_ready_err!(task::spawn(rx_resub_recv.recv()).poll());
+        assert!(is_closed(err));
+
+        for value in 0..capacity {
+            assert_eq!(assert_recv!(rx), value);
+        }
+        assert_closed!(rx.try_recv());
+
+        let mut rx_resub = rx.resubscribe();
+        assert_closed!(rx_resub.try_recv());
+    }
+}
PATCH
cargo test --offline --test sync_broadcast resubscribe_closed

